const ALL_SEEDS = [...AI_TECH_SEED, ...OPTICAL_PHOTONICS_SEED, ...SEMICONDUCTOR_SEED, ...SERVER_POWER_SEED, ...SOFTWARE_PLATFORM_SEED];

function getLimit(): number {
  const arg = process.argv.find((value) => value.startsWith("--limit="));
  if (!arg) {
    return ALL_SEEDS.length;
  }
  const parsed = Number(arg.slice("--limit=".length));
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : ALL_SEEDS.length;
}

function getTickerFilter(): Set<string> | null {
  const arg = process.argv.find((value) => value.startsWith("--tickers="));
  if (!arg) {
    return null;
  }
  const values = arg
    .slice("--tickers=".length)
    .split(",")
    .map((value) => value.trim().toUpperCase())
    .filter(Boolean);
  return values.length > 0 ? new Set(values) : null;
}

async function main(): Promise<void> {
  await initDb();
  const force = process.argv.includes("--force");
  const limit = getLimit();
  const tickerFilter = getTickerFilter();
  const targets = ALL_SEEDS
    .filter((entry) => !tickerFilter || tickerFilter.has(entry.ticker.toUpperCase()))
    .slice(0, limit);
  const summary = { inserted: 0, updated: 0, skipped_existing: 0 };

  for (const entry of targets) {
    const result = await upsertCompanyProfileEnrichment({
      ...entry,
      skipExistingDescription: !force,
    });
    summary[result.status] += 1;
    console.log(`${entry.ticker}: ${result.status}`);
  }

  console.log(JSON.stringify({ theme: "ai_tech_plus_optical_photonics_plus_semiconductors_plus_server_power_plus_software_platform", force, tickerFilter: tickerFilter ? Array.from(tickerFilter) : null, limit: targets.length, ...summary }, null, 2));
}

main()
  .catch((error: unknown) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  })
  .finally(async () => {
    try {
      await getDb().close();
    } catch {
      // ignore close errors during script shutdown
    }
  });